/**
 * 把重复规则的日期算术同步到前后端。
 *
 *   code/shared/utc-recurrence.mjs  ──►  code/app/vendor/ical/utc-recurrence.js
 *                                   ──►  code/web/src/js/utc-recurrence.js
 *
 * 生成物带 AUTO-GENERATED 头注释；`code/web/tests/web-tree-self-contained.test.js`
 * 与 `code/scripts/date-corpus.test.mjs` 都会断言与源一致，漂移即测试失败。
 *
 * 行尾：比对前统一折成 LF。Windows 上 core.autocrlf=true 会把检出的文件写成
 * CRLF，逐字节比对会把「没改过」误报成漂移。
 *
 * 用法：
 *   node scripts/sync-utc-recurrence.mjs            # 写入
 *   node scripts/sync-utc-recurrence.mjs --check    # 只检查，漂移时 exit 1
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const codeRoot = join(here, '..');
const source = join(codeRoot, 'shared', 'utc-recurrence.mjs');
const targets = [
  join(codeRoot, 'app', 'vendor', 'ical', 'utc-recurrence.js'),
  join(codeRoot, 'web', 'src', 'js', 'utc-recurrence.js'),
];
const HEADER = '/* AUTO-GENERATED by code/scripts/sync-utc-recurrence.mjs — 勿手改；源：code/shared/utc-recurrence.mjs */\n';

const toLf = (text) => text.replace(/\r\n/g, '\n');

const body = toLf(readFileSync(source, 'utf8'));
const expected = HEADER + body;
const check = process.argv.includes('--check');
let drift = 0;

for (const target of targets) {
  // 生成物里的 ./date-utils.js 指向各自树里的同名文件：两处都要能提供
// isValidTimeZone / zonedTimeToUTC，否则这份生成物在对应树里直接 import 失败。
  const sibling = join(dirname(target), 'date-utils.js');
  if (!existsSync(sibling)) {
    console.error(`[utc-recurrence] 缺少 ${relative(codeRoot, sibling)}，生成物无法解析 ./date-utils.js`);
    process.exit(1);
  }
  const siblingText = readFileSync(sibling, 'utf8');
  for (const name of ['isValidTimeZone', 'zonedTimeToUTC']) {
    if (!new RegExp(`export (function|const) ${name}\\b`).test(siblingText)) {
      console.error(`[utc-recurrence] ${relative(codeRoot, sibling)} 没有导出 ${name}`);
      process.exit(1);
    }
  }

  let current = null;
  try {
    current = toLf(readFileSync(target, 'utf8'));
  } catch {
    current = null;
  }
  if (current === expected) {
    console.log(`[utc-recurrence] 一致 ${relative(codeRoot, target)}`);
    continue;
  }
  drift += 1;
  if (check) {
    console.log(`[utc-recurrence] 漂移 ${relative(codeRoot, target)}`);
    continue;
  }
  writeFileSync(target, expected, 'utf8');
  console.log(`[utc-recurrence] 已写入 ${relative(codeRoot, target)}`);
}

if (check && drift) {
  console.error(`[utc-recurrence] 有 ${drift} 个生成物与源文件不一致，请运行 node scripts/sync-utc-recurrence.mjs`);
  process.exit(1);
}
